package exam; public class Finalization { public enum Status {DRAFT,RECORDED,VOIDED} public final String id,detail; private Status status; public Finalization(String id,String detail,Status status){this.id=id;this.detail=detail;this.status=status;} public Status status(){return status;} public void record(){if(status!=Status.DRAFT)throw new IllegalStateException("Illegal transition "+status);status=Status.RECORDED;} public void voidRecord(){if(status!=Status.RECORDED)throw new IllegalStateException("Illegal transition "+status);status=Status.VOIDED;}}
